import { describe, it, expect } from "vitest";
import { createFreeCamera } from "@babylonjs/lite";
import { attachFlyControls } from "./fly-controls.ts";

function fakeCanvas() {
    const handlers = new Map<string, Set<any>>();
    const canvas: any = {
        tabIndex: -1,
        hasAttribute: () => false,
        setPointerCapture() {}, releasePointerCapture() {},
        addEventListener(t: string, f: any) { if (!handlers.has(t)) handlers.set(t, new Set()); handlers.get(t)!.add(f); },
        removeEventListener(t: string, f: any) { handlers.get(t)?.delete(f); },
        fire(t: string, ev: any) { for (const f of handlers.get(t) ?? []) f(ev); },
        count() { let n = 0; for (const s of handlers.values()) n += s.size; return n; },
    };
    return canvas;
}

function run(keys: string[], frames = 10) {
    const cam = createFreeCamera({ x: 0, y: 0, z: 0 }, { x: 0, y: 0, z: 1 });
    const canvas = fakeCanvas();
    const scene: any = { _beforeRender: [] as any[] };
    const dispose = attachFlyControls(cam, canvas, scene);
    for (const k of keys) canvas.fire("keydown", { code: k });
    const start = { x: cam.position.x, y: cam.position.y, z: cam.position.z };
    for (let i = 0; i < frames; i++) for (const h of scene._beforeRender) h(16);
    const d = { dx: cam.position.x - start.x, dy: cam.position.y - start.y, dz: cam.position.z - start.z };
    return { d, canvas, scene, dispose, cam };
}

describe("fly controls", () => {
    it("shift alone does not move vertically", () => {
        const { d } = run(["ShiftLeft"]);
        expect(d.dy).toBe(0);
        expect(Math.hypot(d.dx, d.dy, d.dz)).toBe(0);
    });
    it("shift + space: only space rises, boosted", () => {
        const plain = run(["Space"]).d.dy;
        const boosted = run(["Space", "ShiftRight"]).d.dy;
        expect(plain).toBeGreaterThan(0);
        expect(boosted / plain).toBeCloseTo(3, 5);
    });
    it("shift + W boosts 3x forward", () => {
        const plain = run(["KeyW"]).d.dz;
        const boosted = run(["KeyW", "ShiftLeft"]).d.dz;
        expect(plain).toBeGreaterThan(0);
        expect(boosted / plain).toBeCloseTo(3, 5);
    });
    it("pagedown sinks", () => {
        expect(run(["PageDown"]).d.dy).toBeLessThan(0);
    });
    it("cleanup removes listeners and beforeRender hook", () => {
        const { canvas, scene, dispose } = run([]);
        const before = canvas.count();
        expect(before).toBeGreaterThan(0);
        expect(scene._beforeRender.length).toBe(1);
        dispose();
        expect(canvas.count()).toBe(0);
        expect(scene._beforeRender.length).toBe(0);
    });
});
EOF
